def equivSortedParts (n : ℕ) :
    n.Partition ≃
      {w : List ℕ // (w.SortedGE ∧ ∀ x ∈ w, 0 < x) ∧ w.sum = n}

theorem partition_lt_iff {n : ℕ} {μ ν : n.Partition} :
    @LT.lt n.Partition partitionLinearOrder.toLT μ ν ↔
      μ.parts.sort (· ≥ ·) < ν.parts.sort (· ≥ ·)

theorem partition_le_iff {n : ℕ} {μ ν : n.Partition} :
    @LE.le n.Partition partitionLinearOrder.toLE μ ν ↔
      μ.parts.sort (· ≥ ·) ≤ ν.parts.sort (· ≥ ·)

theorem lex_lt_of_dominates_of_ne {n : ℕ} {μ ν : n.Partition}
    (hdom : Dominates μ ν) (hne : μ ≠ ν) :
    sortedParts ν < sortedParts μ

theorem hookLength_lt_hookLength_of_col_lt (μ : YoungDiagram) {i j₁ j₂ : ℕ}
    (h : (i, j₂) ∈ μ) (hj : j₁ < j₂) :
    hookLength μ (i, j₂) < hookLength μ (i, j₁)

theorem hookLength_lt_hookLength_of_row_lt (μ : YoungDiagram) {i₁ i₂ j : ℕ}
    (h : (i₂, j) ∈ μ) (hi : i₁ < i₂) :
    hookLength μ (i₂, j) < hookLength μ (i₁, j)

theorem hookLength_eq_rowLen_sub_of_colLen_le_one {μ : YoungDiagram} (h : μ.colLen 0 ≤ 1) {j : ℕ}
    (hj : j < μ.rowLen 0) :
    hookLength μ (0, j) = μ.rowLen 0 - j
